ALTER TABLE pets ADD COLUMN avatar_asset_id TEXT;
ALTER TABLE pets ADD COLUMN cover_asset_id TEXT;
ALTER TABLE pets ADD COLUMN breed TEXT;
ALTER TABLE pets ADD COLUMN gender TEXT;
ALTER TABLE pets ADD COLUMN sterilized BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE pets ADD COLUMN birthday DATE;
ALTER TABLE pets ADD COLUMN home_date DATE;
CREATE TABLE IF NOT EXISTS pet_certificates (id TEXT PRIMARY KEY, pet_id TEXT NOT NULL, family_id TEXT NOT NULL, type TEXT NOT NULL, name TEXT NOT NULL, number TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (pet_id) REFERENCES pets(id));
CREATE TABLE IF NOT EXISTS pet_personality (id TEXT PRIMARY KEY, pet_id TEXT NOT NULL, family_id TEXT NOT NULL, trait TEXT NOT NULL, value TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (pet_id) REFERENCES pets(id));
CREATE TABLE IF NOT EXISTS pet_questions (id TEXT PRIMARY KEY, pet_id TEXT NOT NULL, family_id TEXT NOT NULL, question TEXT NOT NULL, answer TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (pet_id) REFERENCES pets(id));
CREATE TABLE IF NOT EXISTS pet_health (pet_id TEXT PRIMARY KEY, family_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT '', allergies TEXT NOT NULL DEFAULT '', long_term_medication TEXT NOT NULL DEFAULT '', updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pet_diseases (id TEXT PRIMARY KEY, pet_id TEXT NOT NULL, family_id TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL, details TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pet_vaccines (id TEXT PRIMARY KEY, pet_id TEXT NOT NULL, family_id TEXT NOT NULL, name TEXT NOT NULL, vaccinated_at DATE NOT NULL, details TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pet_birthday_records (id TEXT PRIMARY KEY, pet_id TEXT NOT NULL, family_id TEXT NOT NULL, year INTEGER NOT NULL, age INTEGER NOT NULL, summary TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pet_birthday_media (id TEXT PRIMARY KEY, record_id TEXT NOT NULL, pet_id TEXT NOT NULL, family_id TEXT NOT NULL, type TEXT NOT NULL, asset_id TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pet_birthday_blessings (id TEXT PRIMARY KEY, record_id TEXT NOT NULL, pet_id TEXT NOT NULL, family_id TEXT NOT NULL, user_id TEXT NOT NULL, content TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pet_weights (id TEXT PRIMARY KEY, pet_id TEXT NOT NULL, family_id TEXT NOT NULL, measured_at DATE NOT NULL, weight REAL NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pet_growth_events (id TEXT PRIMARY KEY, pet_id TEXT NOT NULL, family_id TEXT NOT NULL, type TEXT NOT NULL, occurred_at DATE NOT NULL, recorder TEXT NOT NULL, content TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pet_growth_media (id TEXT PRIMARY KEY, event_id TEXT NOT NULL, pet_id TEXT NOT NULL, family_id TEXT NOT NULL, asset_id TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_pet_profile_family ON pet_certificates(family_id, pet_id);
